## Persistent progress: which chambers are open, personal bests, preferences.
extends Node

const PATH := "user://puzzle_magnet_lab.cfg"

var best_moves: Dictionary = {}     # level id -> int
var unlocked: int = 1               # number of chambers available
var sound_on: bool = true

var _config := ConfigFile.new()


func _ready() -> void:
	load_data()
	Sfx.set_sound_on(sound_on)


func load_data() -> void:
	if _config.load(PATH) != OK:
		return
	unlocked = int(_config.get_value("progress", "unlocked", 1))
	sound_on = bool(_config.get_value("settings", "sound", true))
	var raw: Dictionary = _config.get_value("progress", "best", {})
	for key in raw:
		best_moves[String(key)] = int(raw[key])


func save_data() -> void:
	_config.set_value("progress", "unlocked", unlocked)
	_config.set_value("progress", "best", best_moves)
	_config.set_value("settings", "sound", sound_on)
	_config.save(PATH)


func record_result(level_id: String, moves: int, level_index: int, total_levels: int) -> bool:
	var is_new_best := false
	if not best_moves.has(level_id) or moves < int(best_moves[level_id]):
		best_moves[level_id] = moves
		is_new_best = true
	var next_unlock := mini(level_index + 2, total_levels)
	if next_unlock > unlocked:
		unlocked = next_unlock
	save_data()
	return is_new_best


func is_unlocked(index: int) -> bool:
	return index < unlocked


func is_cleared(level_id: String) -> bool:
	return best_moves.has(level_id)


func reset_progress() -> void:
	best_moves.clear()
	unlocked = 1
	save_data()

## Loads and indexes the chamber manifest (res://assets/levels.json).
class_name Levels
extends RefCounted

const PATH := "res://assets/levels.json"

static var _cache: Dictionary = {}


static func data() -> Dictionary:
	if _cache.is_empty():
		var text := FileAccess.get_file_as_string(PATH)
		if text.is_empty():
			push_error("Levels: cannot read %s" % PATH)
			return {"chapters": [], "levels": []}
		var parsed: Variant = JSON.parse_string(text)
		if typeof(parsed) != TYPE_DICTIONARY:
			push_error("Levels: malformed JSON in %s" % PATH)
			return {"chapters": [], "levels": []}
		_cache = parsed
	return _cache


static func chapters() -> Array:
	return data().get("chapters", [])


static func levels() -> Array:
	return data().get("levels", [])


static func count() -> int:
	return levels().size()


static func level_at(index: int) -> Dictionary:
	var list := levels()
	if index < 0 or index >= list.size():
		return {}
	return list[index]


static func index_of_id(id: String) -> int:
	var list := levels()
	for i in range(list.size()):
		if String(list[i].get("id", "")) == id:
			return i
	return -1


static func chapter_of(level: Dictionary) -> Dictionary:
	var list := chapters()
	var idx := int(level.get("chapter", 0))
	if idx < 0 or idx >= list.size():
		return {"name": "CHAMBER", "code": "?", "color": "#49e0d0", "blurb": ""}
	return list[idx]


static func chapter_index(level: Dictionary) -> int:
	return int(level.get("chapter", 0))


static func chapter_color(level: Dictionary) -> Color:
	var chapter := chapter_of(level)
	return Color(String(chapter.get("color", "#49e0d0")))

