## A single chamber card in the index grid.
class_name LevelCard
extends Button

var index: int = 0
var level: Dictionary = {}
var unlocked: bool = true
var best: int = -1
var chapter_color: Color = Palette.SWITCH
var _hovered: bool = false


func setup(idx: int, data: Dictionary, is_unlocked: bool, best_moves: int) -> void:
	index = idx
	level = data
	unlocked = is_unlocked
	best = best_moves
	chapter_color = Levels.chapter_color(data)
	flat = true
	focus_mode = Control.FOCUS_NONE
	mouse_default_cursor_shape = Control.CURSOR_POINTING_HAND if unlocked else Control.CURSOR_FORBIDDEN
	custom_minimum_size = Vector2(196, 138)
	size_flags_horizontal = Control.SIZE_EXPAND_FILL
	tooltip_text = "Chamber %02d - %s" % [index + 1, String(data.get("name", ""))]
	mouse_entered.connect(func(): _hovered = true; queue_redraw())
	mouse_exited.connect(func(): _hovered = false; queue_redraw())


func _draw() -> void:
	var rect := Rect2(Vector2.ZERO, size)
	var pad := 2.0
	var body := rect.grow(-pad)
	var radius := 10.0

	var bg := Palette.PANEL.lerp(chapter_color, 0.05)
	var border := Palette.PANEL_EDGE
	if unlocked:
		if _hovered:
			bg = Palette.PANEL_SOFT.lerp(chapter_color, 0.16)
			border = chapter_color
		elif best >= 0:
			border = chapter_color.darkened(0.35)
	else:
		bg = Palette.PANEL.darkened(0.35)
		border = Palette.PANEL_EDGE.darkened(0.4)

	draw_style_box(UIKit.flat(bg, radius, border, 2.0, 4.0), body)
	# chapter band
	var band := Rect2(body.position + Vector2(10, 10), Vector2(body.size.x - 20, 4))
	draw_rect(band, chapter_color if unlocked else Palette.TEXT_FAINT.darkened(0.4))

	var f := UIKit.font("main")
	var fm := UIKit.font("mono")
	if f == null:
		return

	var number := "%02d" % (index + 1)
	var num_col := Palette.TEXT if unlocked else Palette.TEXT_FAINT
	draw_string(f, body.position + Vector2(12, 48), number, HORIZONTAL_ALIGNMENT_LEFT, -1, 34, num_col)

	var name := String(level.get("name", "?"))
	var name_col := Palette.TEXT if unlocked else Palette.TEXT_FAINT
	draw_string(f, body.position + Vector2(12, 72), name, HORIZONTAL_ALIGNMENT_LEFT, body.size.x - 24, 18, name_col)

	var chapter := Levels.chapter_of(level)
	draw_string(fm, body.position + Vector2(12, 90), String(chapter.get("name", "")), HORIZONTAL_ALIGNMENT_LEFT, body.size.x - 24, 11,
		chapter_color if unlocked else Palette.TEXT_FAINT)

	if not unlocked:
		_draw_lock(body.position + Vector2(body.size.x - 30, 36), Palette.TEXT_FAINT)
	else:
		var stars := UIKit.stars_for(best, int(level.get("par", 0))) if best >= 0 else 0
		for i in range(3):
			var c := Vector2(body.position.x + 16 + float(i) * 20.0, body.position.y + 112)
			_star(c, 8.0, i < stars)

		var label := "BEST %d" % best if best >= 0 else "PAR %d" % int(level.get("par", 0))
		var col := Palette.EXIT if best >= 0 else Palette.TEXT_DIM
		draw_string(fm, body.position + Vector2(body.size.x - 74, 118), label, HORIZONTAL_ALIGNMENT_LEFT, 66, 12, col)

		if best >= 0 and best <= int(level.get("par", 0)):
			draw_style_box(UIKit.flat(Color(Palette.GOLD.r, Palette.GOLD.g, Palette.GOLD.b, 0.15), 6.0, Palette.GOLD, 1.0),
				Rect2(body.position + Vector2(body.size.x - 84, 10), Vector2(72, 20)))
			draw_string(fm, body.position + Vector2(body.size.x - 80, 24), "PERFECT", HORIZONTAL_ALIGNMENT_LEFT, 64, 11, Palette.GOLD)


func _star(center: Vector2, r: float, filled: bool) -> void:
	var pts := PackedVector2Array()
	for i in range(10):
		var ang := -PI * 0.5 + TAU * float(i) / 10.0
		var rad := r if i % 2 == 0 else r * 0.46
		pts.append(center + Vector2(cos(ang), sin(ang)) * rad)
	if filled:
		draw_colored_polygon(pts, Palette.GOLD)
	else:
		draw_polyline(pts + PackedVector2Array([pts[0]]), Color(Palette.TEXT_FAINT.r, Palette.TEXT_FAINT.g, Palette.TEXT_FAINT.b, 0.6), 1.2, true)


func _draw_lock(center: Vector2, color: Color) -> void:
	draw_rect(Rect2(center + Vector2(-9, 0), Vector2(18, 14)), color, true)
	draw_arc(center + Vector2(0, 1), 6.5, PI, TAU, 14, color, 3.0, true)

## Chamber index grouped by chapter, with progress and personal bests.
class_name LevelSelectScreen
extends Control

signal select_level(index: int)
signal back()

const COLUMNS := 4


func _init() -> void:
	set_anchors_preset(Control.PRESET_FULL_RECT)


func _ready() -> void:
	_build()
	Sfx.music("hum", -28.0)


func _build() -> void:
	add_child(Backdrop.new())

	var margin := MarginContainer.new()
	margin.set_anchors_preset(Control.PRESET_FULL_RECT)
	for side in ["left", "right", "top", "bottom"]:
		margin.add_theme_constant_override("margin_" + side, 26)
	add_child(margin)

	var column := VBoxContainer.new()
	column.add_theme_constant_override("separation", 12)
	margin.add_child(column)
	column.add_child(_build_header())

	var scroll := ScrollContainer.new()
	scroll.size_flags_vertical = Control.SIZE_EXPAND_FILL
	scroll.horizontal_scroll_mode = ScrollContainer.SCROLL_MODE_DISABLED
	scroll.follow_focus = true
	column.add_child(scroll)

	var list := VBoxContainer.new()
	list.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	list.add_theme_constant_override("separation", 18)
	scroll.add_child(list)

	var chapters: Array = Levels.chapters()
	for chapter_index in range(chapters.size()):
		list.add_child(_build_chapter(chapter_index, chapters[chapter_index]))

	column.add_child(_build_footer())


func _build_header() -> Control:
	var panel := PanelContainer.new()
	panel.add_theme_stylebox_override("panel", UIKit.panel_style(Color(0.08, 0.12, 0.20), 16.0, true))
	panel.custom_minimum_size = Vector2(0, 78)
	var row := HBoxContainer.new()
	row.add_theme_constant_override("separation", 18)
	panel.add_child(row)

	var back_button := UIKit.icon_button("<  TITLE", 15)
	back_button.pressed.connect(func(): Sfx.play("ui_back", -10.0); back.emit())
	row.add_child(_center(back_button))

	var title_box := VBoxContainer.new()
	title_box.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	title_box.add_theme_constant_override("separation", 0)
	title_box.add_child(UIKit.label("MAGNETICS DIVISION", 12, Palette.SWITCH))
	var title := UIKit.title("CHAMBER INDEX", 30, Palette.TEXT)
	title_box.add_child(title)
	row.add_child(_center(title_box))

	var cleared := 0
	for lvl in Levels.levels():
		if Save.is_cleared(String(lvl.get("id", ""))):
			cleared += 1
	var progress := VBoxContainer.new()
	progress.add_theme_constant_override("separation", 0)
	progress.add_child(UIKit.label("TAGGED", 11, Palette.TEXT_FAINT, HORIZONTAL_ALIGNMENT_RIGHT))
	progress.add_child(UIKit.label("%d / %d" % [cleared, Levels.count()], 24, Palette.EXIT, HORIZONTAL_ALIGNMENT_RIGHT))
	row.add_child(_center(progress))

	var reset := UIKit.icon_button("WIPE SAVE", 13)
	reset.pressed.connect(func():
		Sfx.play("ui_deny", -8.0)
		Save.reset_progress()
		for child in get_children():
			child.queue_free()
		_build())
	row.add_child(_center(reset))

	return panel


func _build_chapter(chapter_index: int, chapter: Dictionary) -> Control:
	var box := VBoxContainer.new()
	box.add_theme_constant_override("separation", 6)
	var color := Color(String(chapter.get("color", "#49e0d0")))

	var header := HBoxContainer.new()
	header.add_theme_constant_override("separation", 12)

	var chip := ColorRect.new()
	chip.color = color
	chip.custom_minimum_size = Vector2(38, 38)
	header.add_child(_center(chip))

	var text := VBoxContainer.new()
	text.add_theme_constant_override("separation", 0)
	text.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	text.add_child(UIKit.label("CHAPTER %s" % String(chapter.get("code", "?")), 11, color))
	text.add_child(UIKit.label(String(chapter.get("name", "")), 22, Palette.TEXT))
	text.add_child(UIKit.label(String(chapter.get("blurb", "")), 12, Palette.TEXT_DIM))
	header.add_child(_center(text))

	var level_ids: Array = []
	for lvl in Levels.levels():
		if int(lvl.get("chapter", -1)) == chapter_index:
			level_ids.append(lvl)
	var done := 0
	for lvl in level_ids:
		if Save.is_cleared(String(lvl.get("id", ""))):
			done += 1
	header.add_child(_center(UIKit.label("%d / %d" % [done, level_ids.size()], 18, Palette.TEXT_DIM, HORIZONTAL_ALIGNMENT_RIGHT)))
	box.add_child(header)

	var rule := ColorRect.new()
	rule.color = Color(color.r, color.g, color.b, 0.35)
	rule.custom_minimum_size = Vector2(0, 1)
	box.add_child(rule)

	var grid := GridContainer.new()
	grid.columns = COLUMNS
	grid.add_theme_constant_override("h_separation", 12)
	grid.add_theme_constant_override("v_separation", 12)
	grid.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	box.add_child(grid)

	for lvl in Levels.levels():
		if int(lvl.get("chapter", -1)) != chapter_index:
			continue
		var index := Levels.index_of_id(String(lvl.get("id", "")))
		var unlocked := Save.is_unlocked(index)
		var card := LevelCard.new()
		card.setup(index, lvl, unlocked, int(Save.best_moves.get(String(lvl.get("id", "")), -1)))
		card.pressed.connect(func():
			if unlocked:
				Sfx.play("ui_confirm", -8.0)
				select_level.emit(index)
			else:
				Sfx.play("ui_deny", -6.0))
		grid.add_child(card)

	return box


func _build_footer() -> Control:
	var panel := PanelContainer.new()
	panel.add_theme_stylebox_override("panel", UIKit.panel_style(Color(0.07, 0.11, 0.18), 14.0, true))
	var row := HBoxContainer.new()
	row.add_theme_constant_override("separation", 22)
	panel.add_child(row)
	row.add_child(_center(UIKit.label("STARS:  CALCULATED FROM MOVES AGAINST THE CHAMBER PAR", 12, Palette.TEXT_DIM)))
	row.add_child(_center(UIKit.label("A  =  PUSH       SAME  =  REPEL       OPPOSITE  =  SWAP", 12, Palette.SWITCH)))
	row.add_child(_center(UIKit.label("HAZARD  =  CRATE KILLER       INVERTER  =  FLIP YOUR FIELD", 12, Palette.HAZARD)))
	return panel


func _center(node: Control) -> Control:
	var wrap := CenterContainer.new()
	wrap.add_child(node)
	return wrap


func _unhandled_input(event: InputEvent) -> void:
	if not visible:
		return
	if event.is_action_pressed("pm_menu"):
		Sfx.play("ui_back", -10.0)
		back.emit()
		get_viewport().set_input_as_handled()

## Tiny illustrated diagrams used by the "how to play" screen.
class_name RuleIcon
extends Control

var kind: String = "move"
var _t: float = 0.0


func _init(what: String = "move", size_px: Vector2 = Vector2(150, 112)) -> void:
	kind = what
	custom_minimum_size = size_px
	mouse_filter = Control.MOUSE_FILTER_IGNORE


func _ready() -> void:
	set_process(true)


func _process(delta: float) -> void:
	_t += delta
	queue_redraw()


func _cell(index: int) -> Rect2:
	var cols := 3
	var rows := 2
	var s := minf(size.x / float(cols), size.y / float(rows))
	var ox := (size.x - s * cols) * 0.5
	var oy := (size.y - s * rows) * 0.5
	var x := index % cols
	var y := index / cols
	return Rect2(Vector2(ox + x * s, oy + y * s), Vector2(s, s))


func _center(i: int) -> Vector2:
	return _cell(i).position + _cell(i).size * 0.5


func _grid() -> void:
	for i in range(6):
		var rect := _cell(i).grow(-2.0)
		draw_style_box(UIKit.flat(Palette.FLOOR_A if i % 2 == 0 else Palette.FLOOR_B, 5.0, Palette.FLOOR_EDGE, 1.0), rect)


func _sprite(i: int, base: Color, deep: Color, label: String, scale: float = 0.62) -> void:
	var c := _center(i)
	var s := _cell(i).size.x * scale
	var rect := Rect2(c - Vector2(s, s) * 0.5, Vector2(s, s))
	draw_style_box(UIKit.flat(deep, s * 0.24, Color(0, 0, 0, 0), 0.0), rect.translated(Vector2(0, 2)))
	draw_style_box(UIKit.flat(base, s * 0.24, base.lightened(0.4), 2.0), rect)
	if label != "":
		var f := UIKit.font("main")
		if f != null:
			var dim := f.get_string_size(label, HORIZONTAL_ALIGNMENT_LEFT, -1, int(s * 0.42))
			draw_string(f, c - Vector2(dim.x * 0.5, -dim.y * 0.32), label, HORIZONTAL_ALIGNMENT_LEFT, -1, int(s * 0.42), Color(1, 1, 1, 0.92))


func _magnet(i: int, pol: String, scale: float = 0.66) -> void:
	var c := _center(i)
	var s := _cell(i).size.x * scale
	var rect := Rect2(c - Vector2(s, s) * 0.5, Vector2(s, s))
	var col := Palette.polarity_color(pol)
	var deep := Palette.polarity_deep(pol)
	var pulse := 0.5 + 0.5 * sin(_t * 3.0)
	draw_circle(c, s * (0.66 + 0.05 * pulse), Color(col.r, col.g, col.b, 0.16))
	draw_style_box(UIKit.flat_corners(col, Vector4(s * 0.24, s * 0.24, 0, 0)), Rect2(rect.position, Vector2(s, s * 0.5)))
	draw_style_box(UIKit.flat_corners(deep, Vector4(0, 0, s * 0.24, s * 0.24)), Rect2(rect.position + Vector2(0, s * 0.5), Vector2(s, s * 0.5)))
	draw_style_box(UIKit.flat_corners(Color(0, 0, 0, 0), Vector4(s * 0.24, s * 0.24, s * 0.24, s * 0.24), col.lightened(0.4), 2.0), rect)
	var f := UIKit.font("main")
	if f != null:
		var fs := int(s * 0.34)
		for pair in [["N", 0.25, 0.95], ["S", 0.75, 0.7]]:
			var dim := f.get_string_size(pair[0], HORIZONTAL_ALIGNMENT_LEFT, -1, fs)
			var p := rect.position + Vector2(rect.size.x * 0.5, rect.size.y * pair[1])
			draw_string(f, p - Vector2(dim.x * 0.5, -dim.y * 0.32), pair[0], HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color(1, 1, 1, pair[2]))


func _player(i: int, pol: String = "N") -> void:
	var c := _center(i)
	var r := _cell(i).size.x * 0.30
	var col := Palette.polarity_color(pol)
	var pulse := 0.5 + 0.5 * sin(_t * 3.0)
	draw_circle(c, r * (1.3 + 0.06 * pulse), Color(col.r, col.g, col.b, 0.18))
	draw_circle(c, r, col)
	draw_circle(c, r * 0.62, col.darkened(0.3))
	draw_circle(c, r * 0.36, Palette.PLAYER_CORE)


func _arrow(from: Vector2, to: Vector2, color: Color, width: float = 3.0) -> void:
	draw_line(from, to, color, width, true)
	var dir := (to - from).normalized()
	var perp := Vector2(-dir.y, dir.x)
	var head := 7.0
	draw_colored_polygon(PackedVector2Array([
		to,
		to - dir * head + perp * head * 0.6,
		to - dir * head - perp * head * 0.6,
	]), color)


func _draw() -> void:
	_grid()
	match kind:
		"move":
			_player(0)
			var c := _center(0)
			var s := _cell(0).size.x
			var n := _center(1)
			_arrow(c + Vector2(s * 0.34, 0), n + Vector2(-s * 0.22, 0), Palette.SWITCH)
			_arrow(n + Vector2(s * 0.1, 0), _center(2) + Vector2(-s * 0.36, 0), Palette.SWITCH, 2.0)
		"crate":
			_player(0)
			_sprite(1, Palette.METAL, Palette.METAL_DEEP, "")
			_arrow(_center(0) + Vector2(18, 0), _center(1) + Vector2(-18, 0), Palette.SWITCH)
			_arrow(_center(1) + Vector2(18, 0), _center(2) + Vector2(-20, 0), Palette.METAL.darkened(0.1), 2.4)
		"repel":
			_player(0)
			_magnet(1, "N")
			var s := _cell(0).size.x
			_arrow(_center(0) + Vector2(s * 0.3, 0), _center(1) + Vector2(-s * 0.3, 0), Palette.SWITCH, 2.0)
			_arrow(_center(1) + Vector2(s * 0.3, 0), _center(2) + Vector2(-s * 0.36, 0), Palette.NORTH)
			var mid := (_center(0) + _center(1)) * 0.5
			for i in range(4):
				var y := mid.y - 12 + float(i) * 8.0
				draw_line(Vector2(mid.x - 4, y), Vector2(mid.x + 4, y + 4), Color(1, 0.5, 0.6, 0.7), 1.6)
		"attract":
			_player(0)
			_magnet(1, "S")
			var s2 := _cell(0).size.x
			_arrow(_center(0) + Vector2(s2 * 0.32, -6), _center(1) + Vector2(-s2 * 0.32, -6), Palette.SOUTH, 2.4)
			_arrow(_center(1) + Vector2(-s2 * 0.32, 8), _center(0) + Vector2(s2 * 0.32, 8), Palette.SOUTH, 2.4)
		"hazard":
			for i in [0, 1, 3, 4, 5]:
				pass
			_sprite(3, Palette.METAL, Palette.METAL_DEEP, "")
			_draw_hazard_icon(_cell(4))
			_arrow(_center(3) + Vector2(18, 0), _center(4) + Vector2(-20, 0), Palette.METAL)
			draw_line(_cell(4).position + Vector2(6, 6), _cell(4).end - Vector2(6, 6), Palette.HAZARD, 3.0)
			_player(5)
		"inverter":
			var cell := _cell(1)
			draw_style_box(UIKit.flat(Palette.SWITCH_DEEP, 6.0, Palette.SWITCH, 2.0), cell.grow(-6.0))
			draw_arc(_center(1), cell.size.x * 0.24, _t * 1.5, _t * 1.5 + PI * 1.3, 18, Palette.SWITCH, 3.0, true)
			_player(1)
			var f := UIKit.font("main")
			if f != null:
				draw_string(f, _center(0) - Vector2(10, 0), "N", HORIZONTAL_ALIGNMENT_LEFT, -1, 26, Palette.NORTH)
				_arrow(_center(0) + Vector2(14, 0), _center(1) + Vector2(-cell.size.x * 0.34, 0), Palette.TEXT_DIM, 2.0)
				draw_string(f, _center(2) - Vector2(10, 0), "S", HORIZONTAL_ALIGNMENT_LEFT, -1, 26, Palette.SOUTH)
				_arrow(_center(1) + Vector2(cell.size.x * 0.34, 0), _center(2) + Vector2(-14, 0), Palette.TEXT_DIM, 2.0)
		"plate":
			var cell := _cell(1)
			draw_style_box(UIKit.flat(Palette.PLATE, 6.0, Palette.PLATE.lightened(0.3), 2.0), cell.grow(-cell.size.x * 0.24))
			_sprite(1, Palette.METAL, Palette.METAL_DEEP, "")
			_arrow(_center(0) + Vector2(18, 0), _center(1) + Vector2(-18, 0), Palette.SWITCH)
			var gate := _cell(2)
			for i in range(3):
				var bar := Rect2(gate.position.x + gate.size.x * (0.2 + 0.26 * float(i)), gate.position.y + 6, gate.size.x * 0.12, gate.size.y - 12)
				draw_style_box(UIKit.flat(Palette.GATE_DEEP.darkened(0.1), 3.0, Palette.GATE, 1.0), bar)
			draw_line(gate.position + Vector2(0, gate.size.y * 0.5), gate.end - Vector2(0, gate.size.y * 0.5), Color(1, 0.3, 0.4, 0.9), 3.0)
		"exit":
			_player(0)
			var c := _center(1)
			var s := _cell(1).size.x
			draw_circle(c, s * 0.34, Color(Palette.EXIT.r, Palette.EXIT.g, Palette.EXIT.b, 0.2))
			for i in range(3):
				draw_arc(c, s * (0.14 + 0.08 * float(i)), _t * (0.8 + 0.4 * float(i)), _t * (0.8 + 0.4 * float(i)) + PI * 1.3, 16, Palette.EXIT, 2.4, true)
			draw_circle(c, s * 0.08, Palette.EXIT)
			_arrow(_center(0) + Vector2(s * 0.34, 0), c - Vector2(s * 0.36, 0), Palette.SWITCH, 2.4)
		_:
			_player(0)


func _draw_hazard_icon(cell: Rect2) -> void:
	var rect := cell.grow(-3.0)
	draw_style_box(UIKit.flat(Palette.HAZARD_DEEP, 5.0, Palette.HAZARD, 2.0), rect)
	for i in range(6):
		var d := float(i) * 12.0 + fmod(_t * 20.0, 12.0)
		var p1 := Vector2(d, 0) if d <= rect.size.x else Vector2(rect.size.x, d - rect.size.x)
		var p2 := Vector2(0, d) if d <= rect.size.y else Vector2(d - rect.size.y, rect.size.y)
		draw_line(rect.position + p1, rect.position + p2, Color(Palette.HAZARD.r, Palette.HAZARD.g, Palette.HAZARD.b, 0.35), 3.0)

